// ── Fetch existing Matt prompts ───────────────────────────────────────────────

const res = await fetch(`${URL}?role=eq.matt&select=id,trigger_type,day_number,mood`, {
  headers: { apikey: KEY, Authorization: `Bearer ${KEY}` }
});
const existing = await res.json();

// Build a lookup: "day:trigger_type:mood" → id
const lookup = {};
for (const row of existing) {
  const key = `${row.day_number}:${row.trigger_type}:${row.mood ?? "null"}`;
  lookup[key] = row.id;
}

let updated = 0, inserted = 0, errors = 0;

for (const day of DAYS) {
  const prompts = [
    { trigger_type: "day",  mood: null,         seq: 1, ...day.thought   },
    { trigger_type: "mood", mood: "anxious",     seq: 1, ...day.anxious   },
    { trigger_type: "mood", mood: "triggered",   seq: 2, ...day.triggered },
    { trigger_type: "mood", mood: "flat",        seq: 3, ...day.flat      },
    { trigger_type: "mood", mood: "hopeful",     seq: 4, ...day.hopeful   },
    { trigger_type: "mood", mood: "struggling",  seq: 5, ...day.struggling},
  ];

  for (const p of prompts) {
    const key = `${day.day}:${p.trigger_type}:${p.mood ?? "null"}`;
    const existingId = lookup[key];

    if (existingId) {
      // Update existing row
      const r = await fetch(`${URL}?id=eq.${existingId}`, {
        method: "PATCH",
        headers: HDR,
        body: JSON.stringify({ title: p.title, brief: p.brief }),
      });
      if (r.ok) { updated++; } else { errors++; console.error("PATCH failed", key, await r.text()); }
    } else {
      // Insert new row (struggling prompts, and any gaps)
      const r = await fetch(URL, {
        method: "POST",
        headers: HDR,
        body: JSON.stringify({
          role: "matt", trigger_type: p.trigger_type,
          day_number: day.day, moment: p.trigger_type === "day" ? null : null,
          mood: p.mood, pathway: null, event: null,
          title: p.title, brief: p.brief, sequence: p.seq, active: true,
        }),
      });
      if (r.ok) { inserted++; } else { errors++; console.error("POST failed", key, await r.text()); }
    }
  }
}

console.log(`Done. Updated: ${updated}, Inserted: ${inserted}, Errors: ${errors}`);
